)}.template-grid,.template-form,.diff-columns{grid-template-columns:1fr}.page-heading h1{font-size:22px}.page-heading>div:last-child{display:flex;flex-wrap:wrap;gap:8px}.page-heading .el-button{margin-left:0}}
</style>
